    /// matches it. Otherwise it records the provided configuration as the initial one (only the
    /// first capture in the session wins) and returns it unchanged.
    fn resolve_initial_request_config(
        &self,
        match_initial_request_config: bool,
        tools: Vec<serde_json::Value>,
        parallel_tool_calls: bool,
        reasoning: Option<Reasoning>,
        text: Option<TextControls>,
    ) -> (Vec<serde_json::Value>, bool, Option<Reasoning>, Option<TextControls>) {
        if match_initial_request_config {
            if let Some(initial) = self.client.state.initial_request_config.get() {
                return (
                    initial.tools.clone(),
                    initial.parallel_tool_calls,
                    initial.reasoning.clone(),
